import OpenAI from "openai";

const derivative: Derivative = async ({ row, ref, db, storage, auth, logging }) => {
  try {
    const openaiApiKey = await rowy.secrets.get("openai");
    if (!openaiApiKey) {
      throw new Error('OpenAI API key not found');
    }
    const openai = new OpenAI({ apiKey: openaiApiKey });

    if (row.uploadImage || row.uploadImage.length > 0 || row.requestTopic || row.requestTopic.length > 0) {
      //Start function
      // Ensure each piece of data is valid; use fallback values if not
      const language = (row.level && row.level.language) || 'English';
      const motherTongue = row.motherTongue || 'en';
      const levelCategory = (row.level && row.level.category) || 'Beginner';
      const levelScore = (row.level && row.level.score !== undefined && row.level.score !== null) ? `${row.level.score}/5` : '1/5';

      // Construct userText with validated or fallback data
      const userText = `Target language: ${language}. User's mother tongue: ${motherTongue}. User's level: ${levelCategory} ${levelScore}`;


      // Check model
      let model = `gpt-4-vision-preview`; // Default model
      let focusOn = `image`; // Default focus
      if (row.requestTopic && row.requestTopic.length > 0) {
        model = `gpt-4-1106-preview`;
      }
      let userContent; // Declare userContent outside the switch to access it later
      switch (model) {
        case "gpt-4-vision-preview":
          userContent = [
            { type: "text", text: userText },
            { type: "image_url", image_url: row.uploadImage },
          ];
          break; 
        case "gpt-4-1106-preview":
          userContent = `Topic: ${row.requestTopic}. ${userText}`;
          focusOn = `topic`;
          break; 
      }

      const systemprompt = `Imagine two characters living within the context of the '${focusOn}'. Creative a conversation between these characters as they interact in this '${focusOn}' setting. Develop a conversation between these two characters that includes greetings, questions, and responses, all while keeping the context of the '${focusOn}' in mind. 
                      Encourage learners to use descriptive language to convey their surroundings and engage in a friendly, informative conversation, fun, happy to learn. This conversation practice is tailored for language learners at the specified level.
                      Generate a set of conversation data in the form of a JSON array object with the following structure:
                      [
                        {
                          "name": "Character Name",
                          "gender": "Character Gender",
                          "text": "Character's Dialogue into target language",
                          "textTranslate": "Character's Dialogue into mother tongue"
                        }
                      ]`;

      // API call to OpenAI
      const response = await openai.chat.completions.create({
        model: model,
        messages: [
          { role: "system", content: systemprompt },
          { role: "user", content: userContent },
        ],
        temperature: 1,
        max_tokens: 4095,
        top_p: 1,
        frequency_penalty: 0,
        presence_penalty: 0,
      });

      const responseData = response.choices[0].message.content;
      if (!responseData) {
        throw new Error('No response data found');
      }

      // Regular expression to find only arry JSON object
      const regex = /(\[.*\])/s; // find a JSON object or array /(\{.*\}|\[.*\])/s
      // Extract JSON string using the regular expression.
      const jsonPart = responseData.match(regex);

      // Safe JSON parsing
      try {
        if (jsonPart) {
          const responseDataJson = JSON.parse(jsonPart);
          await ref.update({ storyJson: responseDataJson });
          return focusOn;
        } else {
          throw new Error('JSON part not found in the response data');
        }
      } catch (e) {
        logging.error('Error parsing JSON:', e.message);
        // Return the raw response data since JSON parsing failed
        return responseData;
      }
    }
    return undefined;

  } catch (error) {
    if (error instanceof OpenAI.APIError) {
      logging.log("OpenAI API Error:", error.name, "Status:", error.status);
    } else {
      logging.log("Error:", error.message);
    }

    return `false`;
  }

};
export default derivative;

import fetch from 'node-fetch';

async function processBatch(batch, elevenlabsApiKey, row, ref, logging) {
  return Promise.all(batch.map(async (textInfo) => {
    if (textInfo.text) {
      let voice;
      switch (textInfo.gender) {
        case 'Male':
          voice = row.elevenlabsVoiceId[1].voiceIdselected;
          break;
        case 'Female':
          voice = row.elevenlabsVoiceId[2].voiceIdselected;
          break;
        default:
          voice = row.elevenlabsVoiceId[0].voiceIdselected;
      }

      const apiUrl = `https://api.elevenlabs.io/v1/text-to-speech/${voice}?optimize_streaming_latency=0`;
      const requestBody = {
        text: textInfo.text,
        model_id: "eleven_multilingual_v2",
        voice_settings: {
          stability: 0.5,
          similarity_boost: 0,
          style: 0,
          use_speaker_boost: true
        }
      };

       const response = await fetch(apiUrl, {
        method: 'POST',
        headers: {
          'Accept': 'audio/mpeg',
          'xi-api-key': elevenlabsApiKey,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(requestBody),
      });

      if (response.ok) {
        const audioBuffer = await response.buffer();
        const file = await rowy.storage.upload.data(audioBuffer, {
          folderPath: ref.path + '/speech/'
        });

        textInfo.textAudio = file.downloadURL;
      } else {
        const errorMessage = `API call failed for text '${textInfo.text}': ${response.status} ${response.statusText}`;
        logging.error(errorMessage);
      }
    }
    return textInfo;
  }));
}
